import{_ as i,C as t,o as r,c as l,E as o,a2 as n}from"./chunks/framework.Cm6XCzck.js";const _=JSON.parse('{"title":"数字员工不是“做完了”，而是“完成声明被独立验收了”","description":"","frontmatter":{"title":"数字员工不是“做完了”，而是“完成声明被独立验收了”","date":"2026-08-05","column":"digital-employee","category":"daily","summary":"计算机操作型数字员工需要一份完成契约，把过程证据、业务结果与失败分类分开。执行者可以声明完成，但不能自行验收自己的声明。","item_id":"Q-20260805-12","source_research_object":"research/analysis/Q-20260805-12-verifiable-completion.md","source_reading_result":"research/reading/Q-20260805-12-verifiable-completion.md","lifecycle":"Published","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true,"outline":"deep","cover":"/assets/covers/verifiable-completion-cover-v2.jpg"},"headers":[],"relativePath":"zh/digital-employee/2026-08-05-verifiable-completion.md","filePath":"zh/digital-employee/2026-08-05-verifiable-completion.md","lastUpdated":1787407830000}'),s={name:"zh/digital-employee/2026-08-05-verifiable-completion.md"};function c(d,e,h,m,p,u){const a=t("ArticleCover");return r(),l("div",null,[o(a,{image:"/assets/covers/verifiable-completion-cover-v2.jpg",kicker:"数字员工 · 每日研究",title:"数字员工不是“做完了”，而是“完成声明被独立验收了”",summary:"计算机操作型数字员工需要一份完成契约，把过程证据、业务结果与失败分类分开。执行者可以声明完成，但不能自行验收自己的声明。",version:"Q-20260805-12",status:"Daily Runtime V5 · 2026-08-05",languageHref:"/en/digital-employee/2026-08-05-verifiable-completion",languageLabel:"English"}),e[0]||(e[0]=n('<h1 id="数字员工不是-做完了-而是-完成声明被独立验收了" tabindex="-1">数字员工不是“做完了”，而是“完成声明被独立验收了” <a class="header-anchor" href="#数字员工不是-做完了-而是-完成声明被独立验收了" aria-label="Permalink to &quot;数字员工不是“做完了”，而是“完成声明被独立验收了”&quot;">​</a></h1><p>计算机操作型数字员工需要一份完成契约，把过程证据、业务结果与失败分类分开。执行者可以声明完成，但不能自行验收自己的声明。</p><h2 id="核心判断" tabindex="-1">核心判断 <a class="header-anchor" href="#核心判断" aria-label="Permalink to &quot;核心判断&quot;">​</a></h2><p>完成是一项受治理的声明，不是最后一个动作、一张最终截图或模型生成的一句话。</p><h2 id="为什么这不是一个单点功能" tabindex="-1">为什么这不是一个单点功能 <a class="header-anchor" href="#为什么这不是一个单点功能" aria-label="Permalink to &quot;为什么这不是一个单点功能&quot;">​</a></h2><p>最终截图可能展示结果表象，却不能证明必需步骤、影响范围或业务授权；过程评分能说明执行质量，却不能证明目标业务状态；失败标签能划分责任，却不自动提供安全重试。它们是不同声明，需要不同证据。</p><h2 id="可落地的最小架构" tabindex="-1">可落地的最小架构 <a class="header-anchor" href="#可落地的最小架构" aria-label="Permalink to &quot;可落地的最小架构&quot;">​</a></h2><p>采用版本化 Completion Claim：包含预期结果、过程证据、确定性状态回读、可选的学习型验证意见、失败与副作用分类，以及独立验收决定。不同检查发生冲突时应保留分歧，而不是强制压成二元结果。</p><h2 id="边界与反证" tabindex="-1">边界与反证 <a class="header-anchor" href="#边界与反证" aria-label="Permalink to &quot;边界与反证&quot;">​</a></h2><p>支撑研究限定于网页任务，基准仅含 246 条轨迹，外部假阳性率仍为 8%。它没有证明回滚、补偿、事务性或企业事故率下降。</p><h2 id="工程结论" tabindex="-1">工程结论 <a class="header-anchor" href="#工程结论" aria-label="Permalink to &quot;工程结论&quot;">​</a></h2><p>优先采用“声明者—证据契约—验证者—验收者”的分离模式。学习型验证只能作为意见，与确定性业务检查和必要的人类权限并存。</p><h2 id="可视化说明" tabindex="-1">可视化说明 <a class="header-anchor" href="#可视化说明" aria-label="Permalink to &quot;可视化说明&quot;">​</a></h2><p>配图用于表达控制边界和状态关系，不表达实验结果，也不制造原始研究对象未支持的量化比较。</p><h2 id="证据与引用" tabindex="-1">证据与引用 <a class="header-anchor" href="#证据与引用" aria-label="Permalink to &quot;证据与引用&quot;">​</a></h2><ol><li><a href="https://github.com/joinwell52-AI/joinwell52/blob/main/research/analysis/Q-20260805-12-verifiable-completion.md" target="_blank" rel="noreferrer">Research Object</a>：本文唯一分析输入，包含研究判断、不确定性、反证和工程影响。</li><li><a href="https://github.com/joinwell52-AI/joinwell52/blob/main/research/reading/Q-20260805-12-verifiable-completion.md" target="_blank" rel="noreferrer">Reading Result</a>：Research Object 的证据边界与来源追溯记录。</li></ol>',16))])}const f=i(s,[["render",c]]);export{_ as __pageData,f as default};
